function seedState() {
 const state=structuredClone({products,plans,companies,entitlements,users,features,overrides,brands,blocks,websites,quotas,releases,notifications,logs,staff});
 const productId=name=>name==='E2B'?'e2b':'web';
 for(const p of legacySnapshot.products){const current=state.products.find(x=>x.id===productId(p.name));Object.assign(current,{code:p.code,notice:p.notice,maintenanceStart:'',recovery:'',status:p.status});}
 for(const f of legacySnapshot.features){let current=state.features.find(x=>x.code===f.code);const extra={product:productId(f.product),name:f.name,code:f.code,version:f.version,status:f.status,scope:f.scope==='內部'?'僅內部測試':f.scope,enabled:f.enabled,owner:f.owner,description:f.desc,plannedAt:f.plannedAt,notice:f.notice,updated:f.updatedAt,clients:['c1','c4']};if(current)Object.assign(current,extra);else state.features.push({id:'legacy-'+f.id,...extra});}
 for(const t of legacySnapshot.templates){const asset={id:'legacy-'+t.id,name:t.name,code:t.code,version:t.version,status:t.status==='已上線'?'已發布':t.status==='等待開通'?'待發布':t.status==='內部測試'?'測試中':t.status,description:t.style,owner:t.owner,updated:t.updatedAt,versions:[t.version],files:t.html,check:t.check,category:t.type,layout:t.style,color:'#185b79',font:'Noto Sans TC',legacyUsage:t.customers};(t.category==='品牌樣式'?state.brands:state.blocks).push(asset);}
 for(const r of legacySnapshot.releases)state.releases.push({id:'legacy-'+r.id,name:r.item,product:productId(r.product),type:'產品版本',asset:productId(r.product),version:r.version,scope:r.scope,status:'已發布',time:r.time,owner:r.user,description:r.item});
 for(const l of legacySnapshot.logs)state.logs.push({id:'legacy-'+l.id,time:l.time,actor:l.user,module:'既有操作紀錄',action:l.action,target:l.target,before:'既有紀錄未保存',after:l.action,reason:'舊版紀錄保留'});
 state.tasks=legacySnapshot.tasks.map(t=>({...t,product:t.target==='E2B'?'e2b':'web',state:'待處理',owner:'王小明'}));
 state.notificationRules=['產品維護公告','功能下架通知','客戶即將到期提醒','額度即將用完提醒','HTML 檢查失敗通知'].map((name,i)=>({id:'rule-'+i,name,enabled:true,channel:'Email、後台站內通知',condition:i===2?'到期前 30 天':i===3?'使用比例達 85%':'事件發生時'}));
 state.settings={'雙因素驗證':'已啟用','閒置登出':'30 分鐘','敏感操作二次確認':'已啟用','稽核保留':'365 天','通知寄送紀錄':'已啟用','匯出權限控管':'已啟用'};
 state.staff.forEach((u,i)=>{u.department=['系統管理','產品營運','網站服務','審核'][i];u.lastLogin=DEMO_DATE+' 09:40';u.modules=i===0?['產品管理','客戶公司','營運管理','系統管理']:i===1?['產品管理','客戶公司','營運管理']:i===2?['產品管理','客戶公司']:[];});
 state.staff.push({id:'legacy-viewer',name:'測試帳號',email:'viewer@demo.local',department:'測試',role:'檢視人員',scope:'唯讀',status:'停用',actions:['檢視'],modules:[],lastLogin:'2026-08-01 10:12'});
 state.entitlements.forEach(e=>{e.mode='正式服務';e.stage='已開通';});state.entitlements.find(e=>e.id==='en5').mode='試用';
 state.entitlements.push({id:'legacy-pending',company:'c3',product:'web',plan:'plan-w3',start:DEMO_DATE,end:'2027-10-04',enabled:true,payment:'合約服務',mode:'正式服務',stage:'等待開通'});
 state.usageByUser=state.quotas.flatMap(q=>{const us=state.users.filter(u=>u.company===q.company&&u.product===q.product&&u.status==='啟用');let remaining=q.used;return us.map((u,i)=>{const used=i===us.length-1?remaining:Math.floor(q.used*(us.length-i)/(us.length*(us.length+1)/2));remaining-=used;return {quota:q.id,user:u.id,used};});});
 return state;
}

// model.js
function daysUntil(date) { return Math.round((Date.parse(date+'T00:00:00Z')-Date.parse(DEMO_DATE+'T00:00:00Z'))/86400000); }
function companyOf(s,id) { return s.companies.find(c=>c.id===id); }
function productOf(s,id) { return s.products.find(p=>p.id===id); }
function entitlementOf(s,company,product) { return s.entitlements.find(e=>e.company===company&&e.product===product); }
function members(s,e) { return s.users.filter(u=>u.company===e.company&&u.product===e.product); }
function seats(s,e) { const list=members(s,e); const active=list.filter(u=>u.status==='啟用').length; const invited=list.filter(u=>u.status==='邀請中').length; const inactive=list.filter(u=>u.status==='停用').length; const limit=s.plans.find(p=>p.id===e.plan)?.limit||0; return {active,invited,inactive,used:active+invited,limit,remaining:Math.max(0,limit-active-invited)}; }
function serviceStatus(s,e) {
  if(e.stage==='等待開通')return {label:'等待開通',tone:'warn',reason:'產品使用權尚未開通'};
  if (!companyOf(s,e.company)?.enabled) return {label:'公司已暫停',tone:'bad',reason:'公司所有產品服務已暫停'};
  if (!productOf(s,e.product)?.enabled) return {label:'產品全域停用',tone:'bad',reason:'產品總開關已關閉'};
  if (!e.enabled) return {label:'產品已暫停',tone:'bad',reason:'此公司的產品使用權已暫停'};
  if (daysUntil(e.start)>0) return {label:'尚未開始',tone:'warn',reason:'此產品使用期間尚未開始'};
  if (daysUntil(e.end)<0) return {label:'已到期',tone:'bad',reason:'此產品使用期間已到期，底下帳號均不可使用'};
  if (daysUntil(e.end)<=30) return {label:'即將到期',tone:'warn',reason:'使用權仍有效'};
  return {label:'使用中',tone:'ok',reason:'使用權有效'};
}
function accountAccess(s,u) {
  if(u.status==='停用') return {label:'不可使用',tone:'bad',reason:'帳號已停用，不占名額'};
  if(u.status==='邀請中') return {label:'等待接受',tone:'warn',reason:'尚未接受邀請，已占用 1 個名額'};
  const e=entitlementOf(s,u.company,u.product); if(!e) return {label:'不可使用',tone:'bad',reason:'沒有此產品使用權'};
  const a=serviceStatus(s,e); return ['使用中','即將到期'].includes(a.label)?{label:'可使用',tone:'ok',reason:'公司、產品使用權與帳號有效'}:{label:'不可使用',tone:'bad',reason:a.reason};
}
function canActivate(s,u) { const e=entitlementOf(s,u.company,u.product); if(!e)return {ok:false,reason:'沒有產品使用權'}; const n=seats(s,e); if(n.used>=n.limit)return {ok:false,reason:`名額已滿（${n.used} / ${n.limit}），無法重新啟用。請先停用其他帳號或調整方案。`}; const st=serviceStatus(s,e); if(!['使用中','即將到期'].includes(st.label)) return {ok:false,reason:st.reason}; return {ok:true,reason:''}; }
function featureAccess(s,company,f) {
  const e=entitlementOf(s,company,f.product); const p=productOf(s,f.product); const o=s.overrides.find(x=>x.company===company&&x.feature===f.id&&(!x.end||daysUntil(x.end)>=0)&&(!x.start||daysUntil(x.start)<=0));
  const quota=s.quotas.find(q=>q.company===company&&q.feature===f.id);
  const checks=[
    {name:'公司狀態',ok:companyOf(s,company)?.enabled,detail:companyOf(s,company)?.enabled?'正常':'整間公司已暫停'},
    {name:'產品總開關',ok:p?.enabled,detail:p?.enabled?'已開啟':'產品全域停用'},
    {name:'產品使用權',ok:!!e&&e.stage!=='等待開通'&&e.enabled&&daysUntil(e.start)<=0&&daysUntil(e.end)>=0,detail:!e?'未開通此產品':e.stage==='等待開通'?'等待開通':!e.enabled?'此產品使用權暫停':daysUntil(e.start)>0?'使用期間尚未開始':daysUntil(e.end)<0?'此產品已到期':`有效至 ${e.end}`},
    {name:'功能總開關',ok:f.enabled,detail:f.enabled?'已開啟':`${f.name}維護或停用中`},
    {name:'開放範圍',ok:f.scope==='全部客戶'||(f.scope==='指定客戶'&&f.clients.includes(company)),detail:f.scope==='全部客戶'?'全部有效客戶':f.scope==='指定客戶'?(f.clients.includes(company)?'已列入指定客戶':'未列入指定客戶'):'僅內部測試'},
    {name:'客戶權限設定',ok:o?.mode!=='強制關閉',detail:o?`${o.mode} · ${o.reason}`:'系統預設'},
    {name:'功能額度',ok:!quota||quota.used<quota.total,detail:quota?`${quota.used} / ${quota.total} ${quota.unit}`:'此展示功能未配置額度限制'}
  ];
  const failed=checks.filter(c=>!c.ok); return {label:failed.length?'不可使用':'可使用',tone:failed.length?'bad':'ok',reason:failed[0]?.detail||'所有條件符合',checks,mode:o?.mode||'系統預設'};
}

// ui.js
function esc(v='') { return String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;'); }
function status(label,tone) { const bad=['已到期','停用','公司已暫停','產品已暫停','產品全域停用','不可使用','停止服務','停權','檢查失敗','發送失敗','已下架']; const warn=['停止新選用','維護中','等待開通','邀請中','等待接受','即將到期','待發布','待發送','待確認']; const info=['開發中','規劃中','測試中','草稿','僅內部測試','指定客戶測試','內部測試']; tone=tone||(bad.includes(label)?'bad':warn.includes(label)?'warn':info.includes(label)?'info':'ok'); return `<span class="status ${tone}"><i></i>${esc(label)}</span>`; }
function btn(label,action,attrs='',style='secondary') { return `<button class="btn ${style}" data-action="${action}" ${attrs}>${label}</button>`; }
function link(label,page,attrs='') {return `<button class="text-link" data-page="${page}" ${attrs}>${esc(label)}</button>`;}
function section(title,description,body,action='') {return `<section class="section"><div class="section-heading"><div><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>${action}</div>${body}</section>`;}
function field(label,key,value,type='text',extra='') { return `<label class="field"><span>${label}</span><input name="${key}" type="${type}" value="${esc(value)}" ${extra}></label>`; }
function select(label,key,options,value) {return `<label class="field"><span>${label}</span><select name="${key}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label>`;}
function note(text,tone='info') {return `<div class="notice ${tone}">${text}</div>`;}
function progress(used,total) {const percent=Math.min(100,Math.round(used/total*100));return `<div class="usage-bar ${percent>=100?'bad':percent>=85?'warn':''}" role="meter" aria-label="使用比例" aria-valuenow="${percent}" aria-valuemin="0" aria-valuemax="100"><span style="width:${percent}%"></span></div>`;}
function steps(labels,current) {return `<ol class="stepper">${labels.map((l,i)=>`<li class="${i===current?'current':i<current?'complete':''}"><button type="button" data-action="wizardStep" data-step="${i}"><span>${String(i+1).padStart(2,'0')}</span>${l}</button></li>`).join('')}</ol>`;}
function tabs(items,current,action='tab') {return `<div class="tabs" role="tablist">${items.map(([id,label,count])=>`<button role="tab" aria-selected="${id===current}" class="${id===current?'active':''}" data-action="${action}" data-tab="${id}">${label}${count!==undefined?`<span>${count}</span>`:''}</button>`).join('')}</div>`;}

